# define proposed transform

def transform(grid):
    h=len(grid); w=len(grid[0])
    rows=[r for r in range(h) for c in range(w) if grid[r][c]]
    if not rows: return [row[:] for row in grid]
    r0=min(rows)
    out=[[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                nc=c+(r-r0)-4
                if 0<=nc<w: out[r][nc]=grid[r][c]
    return out
